-- =========================================================
-- Nomenclador 2025 - Anexo I
-- Script PostgreSQL
-- =========================================================

DROP TABLE IF EXISTS nomenclador_2025 CASCADE;

CREATE TABLE nomenclador_2025 (
    codigo          VARCHAR(20) PRIMARY KEY,
    descripcion     TEXT NOT NULL,
    valor           NUMERIC(14,2) NOT NULL,
    categoria       TEXT
);

