COMMENT ON TABLE nomenclador_2025 IS 'Nomenclador 2025 - Anexo I (valores en pesos argentinos)';
COMMENT ON COLUMN nomenclador_2025.codigo IS 'Código del procedimiento';
COMMENT ON COLUMN nomenclador_2025.descripcion IS 'Descripción del procedimiento';
COMMENT ON COLUMN nomenclador_2025.valor IS 'Valor del procedimiento en $';
